\toprule
\textbf{Config} & IID & DD OOD & AA OOD \\
\midrule
Frozen probing & 1.000$\pm$.000 & .994$\pm$.005 & .939$\pm$.047 \\
E2E fine-tuning & 1.000$\pm$.000 & 1.000$\pm$.000 & \textbf{.997$\pm$.005} \\
\midrule
